# Try various possible tool names for finishing
candidates = [
    "rlm.finish",
    "app.rlm.finish", 
    "world.rlm.finish",
    "funcy.rlm.finish",
    "rlm.complete",
    "rlm.done",
    "task.finish",
    "verifier.finish",
]

for name in candidates:
    try:
        r = await world.call(name, summary="test")
        if r.get("ok"):
            print(f"SUCCESS with '{name}': {r}")
        else:
            print(f"'{name}': ok={r.get('ok')}, error={r.get('error')}")
    except Exception as e:
        print(f"'{name}': ERROR - {e}")
